<script>document.addEventListener('click',e=>{const trigger=e.target.closest('.app-header .hs-dropdown-toggle'),root=trigger?.closest('.hs-dropdown')||e.target.closest('.app-header .hs-dropdown');if(trigger&&root){e.preventDefault();e.stopPropagation();const menu=root.querySelector('.hs-dropdown-menu'),open=menu.classList.contains('hidden');document.querySelectorAll('.app-header .hs-dropdown-menu').forEach(x=>{x.classList.add('hidden');x.closest('.hs-dropdown')?.classList.remove('hs-dropdown-open')});menu.classList.toggle('hidden',!open);root.classList.toggle('hs-dropdown-open',open);return}if(!root)document.querySelectorAll('.app-header .hs-dropdown-menu').forEach(x=>{x.classList.add('hidden');x.closest('.hs-dropdown')?.classList.remove('hs-dropdown-open')})});</script>
<script>document.addEventListener('click',e=>{const trigger=e.target.closest('.app-header .hs-dropdown-toggle');if(trigger){const root=trigger.closest('.hs-dropdown'),menu=root?.querySelector('.hs-dropdown-menu');if(!menu)return;e.preventDefault();e.stopImmediatePropagation();const open=menu.style.display!=='block';document.querySelectorAll('.app-header .hs-dropdown-menu').forEach(x=>{x.style.display='none';x.style.opacity='0';x.closest('.hs-dropdown')?.classList.remove('hs-dropdown-open')});if(open){menu.style.cssText+=';display:block;opacity:1;position:absolute;inset:auto 0 auto auto;top:calc(100% + .5rem);z-index:10001';root.classList.add('hs-dropdown-open')}return}if(!e.target.closest('.app-header .hs-dropdown'))document.querySelectorAll('.app-header .hs-dropdown-menu').forEach(x=>{x.style.display='none';x.style.opacity='0';x.closest('.hs-dropdown')?.classList.remove('hs-dropdown-open')})},true);</script>
<script>(()=>{let state;const size=280,draw=(canvas,edge=size)=>{const c=canvas.getContext('2d'),i=state.image,z=+state.zoom.value,base=Math.max(edge/i.naturalWidth,edge/i.naturalHeight)*z,w=i.naturalWidth*base,h=i.naturalHeight*base,x=(edge-w)/2+(+state.x.value/100)*(Math.max(0,w-edge)/2),y=(edge-h)/2+(+state.y.value/100)*(Math.max(0,h-edge)/2);canvas.width=canvas.height=edge;c.clearRect(0,0,edge,edge);c.drawImage(i,x,y,w,h)},preview=()=>{draw(state.canvas);const target=document.querySelector('[data-avatar-preview]');if(target){const image=new Image();image.src=state.canvas.toDataURL('image/jpeg',.9);image.className='size-full object-cover';target.replaceChildren(image)}};document.addEventListener('change',event=>{const input=event.target.closest('[data-avatar-input]'),file=input?.files?.[0];if(!input||!file)return;event.stopImmediatePropagation();const host=input.closest('label'),old=host.querySelector('.eduvixo-avatar-crop');old?.remove();const box=document.createElement('div');box.className='eduvixo-avatar-crop is-visible';box.innerHTML='<p class="mb-3 text-xs text-default-500">Choose the visible square crop. The saved image is optimized to 320 × 320 px.</p><canvas></canvas><label>Zoom<input data-crop="zoom" type="range" min="1" max="3" value="1" step=".01"></label><label>Horizontal<input data-crop="x" type="range" min="-100" max="100" value="0"></label><label>Vertical<input data-crop="y" type="range" min="-100" max="100" value="0"></label>';host.append(box);const image=new Image();state={input,image,canvas:box.querySelector('canvas'),zoom:box.querySelector('[data-crop=zoom]'),x:box.querySelector('[data-crop=x]'),y:box.querySelector('[data-crop=y]')};image.onload=preview;image.src=URL.createObjectURL(file);box.querySelectorAll('input').forEach(control=>control.addEventListener('input',preview))},true);document.addEventListener('submit',event=>{const form=event.target;if(form.action!==location.origin+'/profile'||!state||form.dataset.avatarCropReady==='1'){if(form.dataset.avatarCropReady==='1')delete form.dataset.avatarCropReady;return}event.preventDefault();event.stopImmediatePropagation();const output=document.createElement('canvas');draw(output,320);output.toBlob(blob=>{if(!blob)return;const transfer=new DataTransfer();transfer.items.add(new File([blob],'profile-avatar.jpg',{type:'image/jpeg'}));state.input.files=transfer.files;form.dataset.avatarCropReady='1';form.requestSubmit()},'image/jpeg',.9)},true)})();</script>
